const body = $input.first().json.body || {};
const username = (body.username || '').trim();
const password = (body.password || '').trim();

if (!username || !password) {
  return [{
    json: {
      error: true,
      statusCode: 400,
      message: 'Username and password are required.'
    }
  }];
}

return [{
  json: {
    username,
    password,
    clientIp: $input.first().json.headers['x-forwarded-for'] || '127.0.0.1'
  }
}];

const rows = $input.all();
if (!rows || rows.length === 0 || !rows[0].json || !rows[0].json.user_id) {
  return [{
    json: {
      success: false,
      statusCode: 401,
      message: 'Invalid credentials or inactive account.'
    }
  }];
}

const user = rows[0].json;
const tokenPayload = {
  userId: user.user_id,
  clientId: user.client_id,
  username: user.username,
  role: user.role,
  hospitalName: user.hospital_name || 'Shreeji Central Admin',
  exp: Math.floor(Date.now() / 1000) + (8 * 3600)
};

const token = Buffer.from(JSON.stringify(tokenPayload)).toString('base64');

return [{
  json: {
    success: true,
    statusCode: 200,
    message: 'Login successful',
    token: token,
    user: {
      id: user.user_id,
      clientId: user.client_id,
      clientCode: user.client_code,
      username: user.username,
      email: user.email,
      fullName: user.full_name,
      role: user.role,
      hospitalName: user.hospital_name || 'Central Admin',
      destinationName: user.destination_name || ''
    }
  }
}];
